```javascript
import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, color } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const timelines = [];
  const cleanups = [];

  // ──────────────────────────────────────────────────────────────────
  // 1. BUILD BACKDROP GRADIENT PLANE
  // ──────────────────────────────────────────────────────────────────
  const backdropGeom = new THREE.PlaneGeometry(7, 6);
  const gradStops = config.intent?.visualSpec?.colors?.gradientStops ?? [
    { at: 0, hex: '#0b0b10' },
    { at: 1, hex: '#16161d' }
  ];

  const gradCol0 = new THREE.Color(gradStops[0].hex);
  const gradCol1 = new THREE.Color(gradStops[1].hex);

  const gradMat = new MeshBasicNodeMaterial();
  const gradUv = uv();
  gradMat.colorNode = mix(color(gradCol0), color(gradCol1), gradUv.y);

  const backdrop = new THREE.Mesh(backdropGeom, gradMat);
  backdrop.position.z = -2.5;
  group.add(backdrop);

  // ──────────────────────────────────────────────────────────────────
  // 2. PARTICLE CONSTELLATION CORE + FIELD
  // ──────────────────────────────────────────────────────────────────
  const totalCount = 1200;
  const coreCount = 90;
  const fieldCount = totalCount - coreCount;

  // Core: sphere of radius 0.5 at origin, #ff2a38, emissive 1.8, additive
  const corePositions = new Float32Array(coreCount * 3);
  const coreEmissives = new Float32Array(coreCount * 3);
  const coreAccent = new THREE.Color('#ff2a38');

  for (let i = 0; i < coreCount; i++) {
    const phi = Math.random() * Math.PI * 2;
    const theta = Math.acos(Math.random() * 2 - 1);
    const r = 0.5 * Math.cbrt(Math.random()); // uniform sphere distribution

    corePositions[i * 3 + 0] = r * Math.sin(theta) * Math.cos(phi);
    corePositions[i * 3 + 1] = r * Math.sin(theta) * Math.sin(phi);
    corePositions[i * 3 + 2] = r * Math.cos(theta);

    coreEmissives[i * 3 + 0] = coreAccent.r;
    coreEmissives[i * 3 + 1] = coreAccent.g;
    coreEmissives[i * 3 + 2] = coreAccent.b;
  }

  // Field: ellipsoid 6x4x5 around z=-1.5
  const fieldPositions = new Float32Array(fieldCount * 3);
  const fieldOpacities = new Float32Array(fieldCount);
  const paperCol = new THREE.Color('#e8ecf2');

  for (let i = 0; i < fieldCount; i++) {
    const phi = Math.random() * Math.PI * 2;
    const theta = Math.acos(Math.random() * 2 - 1);
    const u = Math.cbrt(Math.random());

    const rx = 3, ry = 2, rz = 2.5;
    fieldPositions[i * 3 + 0] = u * rx * Math.sin(theta) * Math.cos(phi);
    fieldPositions[i * 3 + 1] = u * ry * Math.sin(theta) * Math.sin(phi);
    fieldPositions[i * 3 + 2] = -1.5 + u * rz * Math.cos(theta);

    // Depth falloff: z=0 → 0.9 opacity, z=-5 → 0.15 opacity
    const z = fieldPositions[i * 3 + 2];
    const depthFactor = Math.max(0.15, 0.9 - (z / -5) * (0.9 - 0.15));
    fieldOpacities[i] = depthFactor;
  }

  // Core icosahedron
  const coreIcosGeom = new THREE.IcosahedronGeometry(0.012, 1);
  const coreMat = new MeshStandardNodeMaterial();
  coreMat.color.setHex(0xff2a38);
  coreMat.metalness = 0;
  coreMat.roughness = 1;
  coreMat.emissiveIntensity = 1.8;
  coreMat.emissive.setHex(0xff2a38);
  coreMat.transparent = true;
  coreMat.blending = THREE.AdditiveBlending;

  const coreInstances = new THREE.InstancedMesh(coreIcosGeom, coreMat, coreCount);
  coreInstances.instanceMatrix.setUsage(THREE.DynamicDrawUsage);

  const coreMatrix = new THREE.Matrix4();
  for (let i = 0; i < coreCount; i++) {
    coreMatrix.setPosition(
      corePositions[i * 3],
      corePositions[i * 3 + 1],
      corePositions[i * 3 + 2]
    );
    coreInstances.setMatrixAt(i, coreMatrix);
  }
  coreInstances.instanceMatrix.needsUpdate = true;
  group.add(coreInstances);

  // Field icosahedron
  const fieldIcosGeom = new THREE.IcosahedronGeometry(0.012, 1);
  const fieldMat = new MeshStandardNodeMaterial();
  fieldMat.color.copy(paperCol);
  fieldMat.metalness = 0;
  fieldMat.roughness = 1;
  fieldMat.emissiveIntensity = 0.9;
  fieldMat.emissive.copy(paperCol);
  fieldMat.transparent = true;

  const fieldInstances = new THREE.InstancedMesh(fieldIcosGeom, fieldMat, fieldCount);
  fieldInstances.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
  fieldInstances.instanceColor = new THREE.InstancedBufferAttribute(new Float32Array(fieldCount * 3), 3);

  const fieldMatrix = new THREE.Matrix4();
  for (let i = 0; i < fieldCount; i++) {
    fieldMatrix.setPosition(
      fieldPositions[i * 3],
      fieldPositions[i * 3 + 1],
      fieldPositions[i * 3 + 2]
    );
    fieldInstances.setMatrixAt(i, fieldMatrix);
    const opacity = fieldOpacities[i];
    fieldInstances.instanceColor.setXYZ(i, opacity, opacity, opacity);
  }
  fieldInstances.instanceMatrix.needsUpdate = true;
  fieldInstances.instanceColor.needsUpdate = true;
  group.add(fieldInstances);

  // ──────────────────────────────────────────────────────────────────
  // 3. FOG
  // ──────────────────────────────────────────────────────────────────
  const scene = group; // We'll attach fog to the returned group's userData for the renderer
  group.userData.fogConfig = {
    color: '#0b0b10',
    near: 4,
    far: 10
  };

  // ──────────────────────────────────────────────────────────────────
  // 4. TEXT CONTENT
  // ──────────────────────────────────────────────────────────────────
  const heroText = ctx.fontAtlas.createText('NOVA ATELIER', {
    fontSize: 124,
    color: '#e8ecf2',
    align: 'center'
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText('Precision instruments for the dark hours.', {
    fontSize: 40,
    color: '#e8ecf2',
    align: 'center'
  });
  subheadText.position.set(0, 0.5 - 0.75, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText('EST. 2019 / GENEVA AND KYOTO', {
    fontSize: 18,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 1.44 // 0.08em * 18px
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // ──────────────────────────────────────────────────────────────────
  // 5. PARTICLE-EMERGE PRIMITIVE (load trigger, 1400ms)
  // ──────────────────────────────────────────────────────────────────
  const primitiveResult = ctx.primitives['particle-emerge'](group, {
    count: 1200,
    durationMs: 1400
  });
  if (primitiveResult && primitiveResult.cleanup) {
    cleanups.push(primitiveResult.cleanup);
  }
  if (primitiveResult && primitiveResult.timeline) {
    timelines.push(primitiveResult.timeline);
  }

  // ──────────────────────────────────────────────────────────────────
  // 6. AMBIENT DRIFT: Each particle orbits anchor ±0.04 at 0.05 Hz
  // ──────────────────────────────────────────────────────────────────
  const driftTimeline = gsap.timeline({ repeat: -1 });
  const driftDuration = 1 / 0.05; // 20 seconds for one full cycle

  // Animate core instances with subtle orbit
  for (let i = 0; i < coreCount; i++) {
    const originX = corePositions[i * 3];
    const originY = corePositions[i * 3 + 1];
    const originZ = corePositions[i * 3 + 2];
    const phase = (i / coreCount) * Math.PI * 2;

    driftTimeline.to(
      { t: 0 },
      {
        t: 1,
        duration: driftDuration,
        ease: 'none',
        onUpdate: function() {
          const angle = (this.targets()[0].t * Math.PI * 2 + phase) % (Math.PI * 2);
          const offsetX = Math.cos(angle) * 0.04;
          const offsetY = Math.sin(angle) * 0.04;

          const mat = new THREE.Matrix4();
          mat.setPosition(originX + offsetX, originY + offsetY, originZ);
          coreInstances.setMatrixAt(i, mat);
          coreInstances.instanceMatrix.needsUpdate = true;
        }
      },
      0
    );
  }

  // Animate field instances with subtle orbit
  for (let i = 0; i < fieldCount; i++) {
    const originX = fieldPositions[i * 3];
    const originY = fieldPositions[i * 3 + 1];
    const originZ = fieldPositions[i * 3 + 2];
    const phase = (i / fieldCount) * Math.PI * 2;

    driftTimeline.to(
      { t: 0 },
      {
        t: 1,
        duration: driftDuration,
        ease: 'none',
        onUpdate: function() {
          const angle = (this.targets()[0].t * Math.PI * 2 + phase) % (Math.PI * 2);
          const offsetX = Math.cos(angle) * 0.04;
          const offsetY = Math.sin(angle) * 0.04;

          const mat = new THREE.Matrix4();
          mat.setPosition(originX + offsetX, originY + offsetY, originZ);
          fieldInstances.setMatrixAt(i, mat);
          fieldInstances.instanceMatrix.needsUpdate = true;
        }
      },
      0
    );
  }

  timelines.push(driftTimeline);

  // ──────────────────────────────────────────────────────────────────
  // 7. CORE PULSE: Emissive intensity 1.5 to 1.8 sine at 0.1 Hz
  // ──────────────────────────────────────────────────────────────────
  const pulsePeriod = 1 / 0.1; // 10 seconds
  const pulseTimeline = gsap.timeline({ repeat: -1 });
  pulseTimeline.to(
    coreMat,
    {
      emissiveIntensity: 1.8,
      duration: pulsePeriod / 2,
      ease: 'sine.inOut'
    },
    0
  ).to(
    coreMat,
    {
      emissiveIntensity: 1.5,
      duration: pulsePeriod / 2,
      ease: 'sine.inOut'
    }
  );
  timelines.push(pulseTimeline);

  // ──────────────────────────────────────────────────────────────────
  // 8. CLEANUP
  // ──────────────────────────────────────────────────────────────────
  group.userData.cleanup = function() {
    timelines.forEach(tl => {
      if (tl && typeof tl.kill === 'function') {
        tl.kill();
      }
    });
    cleanups.forEach(fn => {
      if (typeof fn === 'function') fn();
    });
    backdropGeom.dispose();
    gradMat.dispose();
    coreIcosGeom.dispose();
    coreMat.dispose();
    fieldIcosGeom.dispose();
    fieldMat.dispose();
  };

  return group;
}
